package app.space.notes;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import androidx.test.platform.app.InstrumentationRegistry;
import android.graphics.*;
import android.graphics.pdf.PdfRenderer;
import android.os.ParcelFileDescriptor;
import org.junit.Test;
import org.junit.runner.RunWith;
import java.io.*;
import java.util.*;
import app.space.notes.domain.*;
import app.space.notes.runtime.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

@RunWith(AndroidJUnit4.class)
public class PdfExportTest {
    private File export(Note note) throws Exception {File f=File.createTempFile("pdf-test-",".pdf",InstrumentationRegistry.getInstrumentation().getTargetContext().getCacheDir());try(OutputStream out=new FileOutputStream(f)){PdfExporter.write(Arrays.asList(note),out);}return f;}
    private int pages(File file) throws Exception {try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer renderer=new PdfRenderer(fd)){return renderer.getPageCount();}}
    @Test public void emptyNoteProducesReadablePdf() throws Exception {File f=export(Note.create(1));try{assertEquals(1,pages(f));assertTrue(f.length()>100);}finally{f.delete();}}
    @Test public void longUnicodeTextPaginatesWithoutDroppingFinalPage() throws Exception {StringBuilder text=new StringBuilder();for(int i=0;i<300;i++)text.append(i+" ಕನ್ನಡ Hindi नोट\n");File f=export(Note.create(1).edit("Long",text.toString(),2));try{assertTrue(pages(f)>4);}finally{f.delete();}}
    @Test public void flowchartAddsVectorPageAndRendersVisibleContent() throws Exception {Diagram d=Diagram.empty().put(new Diagram.Node("a","decision","Yes?",100,100,240,160,6)).put(new Diagram.Node("b","terminator","End",100,500,240,100,2)).connect("a","b","Yes");File f=export(Note.create(1).diagram(d,2));try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(f,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer renderer=new PdfRenderer(fd)){assertEquals(2,renderer.getPageCount());try(PdfRenderer.Page page=renderer.openPage(1)){Bitmap bitmap=Bitmap.createBitmap(595,842,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.WHITE);page.render(bitmap,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);int colored=0;for(int y=80;y<600;y+=4)for(int x=50;x<500;x+=4){int color=bitmap.getPixel(x,y);if(Color.red(color)!=Color.blue(color))colored++;}assertTrue("Colored shapes must render on exported PDF page",colored>50);bitmap.recycle();}}finally{f.delete();}}
    @Test public void checklistExportsAndOriginalRemainsStructured() throws Exception {Note n=Note.create(1).convert(2);File f=export(n);try{assertEquals(1,pages(f));assertTrue(n.checklist);}finally{f.delete();}}
    @Test public void richSpansOffsetAfterTitleWithoutCrashing() throws Exception {File f=export(Note.create(1).rich("Title","Hello world",Arrays.asList(new Note.Mark("bold",0,5),new Note.Mark("h1",6,11)),2));try{assertEquals(1,pages(f));}finally{f.delete();}}
    private void review(File file,String name)throws Exception{File dir=new File(InstrumentationRegistry.getInstrumentation().getTargetContext().getFilesDir(),"pdf-review");assertTrue(dir.isDirectory() || dir.mkdirs());try(InputStream in=new FileInputStream(file);OutputStream out=new FileOutputStream(new File(dir,name))){byte[] buffer=new byte[8192];int count;while((count=in.read(buffer))!=-1)out.write(buffer,0,count);}}
    private Bitmap renderFirst(File file)throws Exception{try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer renderer=new PdfRenderer(fd);PdfRenderer.Page page=renderer.openPage(0)){Bitmap bitmap=Bitmap.createBitmap(595,842,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.WHITE);page.render(bitmap,null,null,PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY);return bitmap;}}
    @Test public void canonicalWrappedLinksHaveRealAnnotationsAcrossPagesAndTablePanels()throws Exception{
        String text=String.join(" ",Collections.nCopies(500,"Wrapped link"));RichText rich=new RichText(text,Arrays.asList(new Note.Mark("link",0,text.length(),"https://example.com/notes?q=one&lang=kn"),new Note.Mark("size",0,text.length(),"24"),new Note.Mark("number",0,text.length(),"1")));
        TextTable table=TextTable.empty(2,5).withRichCell(0,4,new RichText("Column five link",Arrays.asList(new Note.Mark("link",0,16,"https://example.com/table"))));
        Note note=Note.create(1).withContent(new DocumentContent(Arrays.asList(DocumentContent.Block.text("body",rich),DocumentContent.Block.table("table","Table01",table))),2);byte[] before=DocumentCodec.encode(Arrays.asList(note));File file=export(note);try{assertTrue(pages(file)>2);String pdf=new String(java.nio.file.Files.readAllBytes(file.toPath()),java.nio.charset.StandardCharsets.ISO_8859_1);assertTrue(pdf.contains("/Subtype /Link"));assertTrue(pdf.contains("/Prev "));assertTrue(Arrays.equals(before,DocumentCodec.encode(Arrays.asList(note))));review(file,"canonical-links.pdf");}finally{file.delete();}
    }
    @Test public void legacyLinkAndNonAsciiUrlExportAsSafeUriAnnotation()throws Exception{String url="https://example.com/ಪದ?q=one(two)";Note note=Note.create(1).rich("Legacy","Open page",Arrays.asList(new Note.Mark("link",0,9,url)),2);File file=export(note);try{assertEquals(1,pages(file));String pdf=new String(java.nio.file.Files.readAllBytes(file.toPath()),java.nio.charset.StandardCharsets.ISO_8859_1);assertTrue(pdf.contains("/S /URI"));assertTrue(!pdf.contains("/JavaScript"));review(file,"legacy-link.pdf");}finally{file.delete();}}
    @Test public void writingGuidesAreOptInRenderedAndNeverMutateTheNote()throws Exception{Note note=Note.create(1).withContent(new DocumentContent(Arrays.asList(DocumentContent.Block.text("body",new RichText("Line one\nLine two\nLine three",Collections.emptyList())))).withWritingLines(true),2);byte[] before=DocumentCodec.encode(Arrays.asList(note));File plain=export(note),ruled=File.createTempFile("pdf-guides-",".pdf",InstrumentationRegistry.getInstrumentation().getTargetContext().getCacheDir());try{try(OutputStream out=new FileOutputStream(ruled)){PdfExporter.write(Arrays.asList(note),out,true);}assertEquals(pages(plain),pages(ruled));Bitmap a=renderFirst(plain),b=renderFirst(ruled);try{int difference=0;for(int y=0;y<842;y++)for(int x=0;x<595;x++)if(a.getPixel(x,y)!=b.getPixel(x,y))difference++;assertTrue("Printed guide ink must be visible",difference>100);}finally{a.recycle();b.recycle();}assertTrue(Arrays.equals(before,DocumentCodec.encode(Arrays.asList(note))));review(plain,"guides-off.pdf");review(ruled,"guides-on.pdf");}finally{plain.delete();ruled.delete();}}
    @Test public void unsupportedPdfAndUnsafeLinksFailWithoutModifyingInput()throws Exception{File file=File.createTempFile("invalid-generated-",".pdf",InstrumentationRegistry.getInstrumentation().getTargetContext().getCacheDir());byte[] original="not a generated Android PDF".getBytes(java.nio.charset.StandardCharsets.US_ASCII);try{java.nio.file.Files.write(file.toPath(),original);try{PdfLinks.annotate(file,Arrays.asList(new PdfLinks.Link(1,48,48,100,70,"https://example.com")));org.junit.Assert.fail("Unsupported PDFs must fail closed");}catch(IOException expected){}assertTrue(Arrays.equals(original,java.nio.file.Files.readAllBytes(file.toPath())));for(String uri:Arrays.asList("javascript:alert(1)","file:///sdcard/private","https://example.com/\n"))try{new PdfLinks.Link(1,48,48,100,70,uri);org.junit.Assert.fail("Unsafe action accepted");}catch(IllegalArgumentException expected){}}finally{file.delete();}}

}
